def addr_backward(grad_output, vec1, vec2, beta=1.0, alpha=1.0):
    """Compute all addr input gradients with one tiled Triton launch."""
    logger.debug("GEMS ADDR_BACKWARD")
    M, N = grad_output.shape
    grad_input = torch.empty_like(grad_output)
    grad_vec1 = torch.empty_like(vec1)
    grad_vec2 = torch.empty_like(vec2)

    num_self_row_tiles = triton.cdiv(M, BACKWARD_BLOCK_M)
    num_self_col_tiles = triton.cdiv(N, BACKWARD_BLOCK_N)
    num_self_tiles = num_self_row_tiles * num_self_col_tiles
    # One masked reduction tile keeps the single-launch contract for empty axes.
    num_vec1_tiles = max(1, num_self_row_tiles)
    num_vec2_tiles = max(1, num_self_col_tiles)
    grid = (num_self_tiles + num_vec1_tiles + num_vec2_tiles,)
    with torch_device_fn.device(grad_output.device):
        addr_backward_kernel[grid](
            grad_output,
            vec1,
            vec2,
            grad_input,
            grad_vec1,
            grad_vec2,
            alpha,
            beta,
            grad_output.stride(0),
            grad_output.stride(1),
            vec1.stride(0),
            vec2.stride(0),
            grad_input.stride(0),
            grad_input.stride(1),
            grad_vec1.stride(0),
            grad_vec2.stride(0),
            M=M,
            N=N,
            NUM_SELF_COL_TILES=num_self_col_tiles,
            NUM_SELF_TILES=num_self_tiles,
            NUM_VEC1_TILES=num_vec1_tiles,
            BLOCK_M=BACKWARD_BLOCK_M,
            BLOCK_N=BACKWARD_BLOCK_N,
            num_warps=4,
        )
    return grad_input, grad_vec1, grad_vec2


class AddrFunction(torch.autograd.Function):
    @staticmethod
    def forward(ctx, input, vec1, vec2, beta, alpha):
        ctx.save_for_backward(vec1, vec2)
